package com.skycraft.audio;

import net.minecraftforge.eventbus.api.IEventBus;
import net.minecraftforge.fml.ModLoadingContext;
import net.minecraftforge.fml.config.ModConfig;

/**
 * Skycraft's own audio: the province soundtracks (driven by {@code world.client.MusicController}), the ambience engine
 * ({@code audio.client.AmbienceEngine}), environmental reverb and occlusion ({@code audio.client.Acoustics}) and the
 * creature, shout, spell and UI sound events ({@link AudioSounds}). Every shipped sound is original and procedurally
 * generated by the scripts in {@code tools/music/} (docs/MUSIC.md).
 */
public final class AudioModule {
    private AudioModule() {}

    /** Registers the sound events and the client config. Called from the mod constructor. */
    public static void init(IEventBus modBus) {
        AudioSounds.init(modBus);
        ModLoadingContext.get().registerConfig(ModConfig.Type.CLIENT, AudioConfig.CLIENT_SPEC, "skycraft-audio-client.toml");
    }
}
